+		case authority.DenialMalformed:
+			message = msgMalformed
+		case authority.DenialExpired:
+			message = msgExpired
+		}
+		return nil, &protocol.AuthorizationError{Status: http.StatusUnauthorized, Err: errors.New(message)}
+	}
